1	import { test } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { createFakeDom, createFakeFetch, loadApp, flush } from './helpers/fake-dom.mjs';
4	
5	const NO_REPLY = 'Could not reach the server.';
6	const unhandled = [];
7	process.on('unhandledRejection', (reason) => unhandled.push(reason));
8	
9	const B1 = { id: 1, room: 'Aurora', title: 'Standup', date: '2026-11-03', start: '09:00', end: '10:00' };
10	const B2 = { id: 2, room: 'Cosmos', title: 'Review', date: '2026-11-01', start: '13:00', end: '14:30' };
11	
12	function boot() {
13	  const dom = createFakeDom();
14	  const f = createFakeFetch(dom.log);
15	  loadApp({ document: dom.document, fetch: f.fetch });
16	  const els = dom.elements;
17	  return { dom, f, els, log: dom.log, rooms: f.calls[0], list: f.calls[1] };
18	}
19	
20	async function bootWithList(bookings) {
21	  const t = boot();
22	  t.f.respond(t.list, 200, { bookings });
23	  await flush();
24	  return t;
25	}
26	
27	function plain(value) {
28	  return JSON.parse(JSON.stringify(value));
29	}
30	
31	function itemsOf(t) {
32	  return t.els['booking-list'].children;
33	}
34	
35	async function fillAndSubmit(t) {
36	  const { els } = t;
37	  els.room.value = 'Aurora';
38	  els.title.value = '  Standup  ';
39	  els.date.value = '2026-11-03';
40	  els.start.value = '09:00';
41	  els.end.value = '10:00';
42	  const ev = { prevented: 0, preventDefault() { this.prevented += 1; } };
43	  els['booking-form'].dispatch('submit', ev);
44	  return ev;
45	}
46	
47	// ---------- Load ----------
48	
49	test('load: two fetches start synchronously with one argument', () => {
50	  const t = boot();
51	  assert.equal(t.f.calls.length, 2);
52	  assert.equal(t.f.calls[0].url, '/api/rooms');
53	  assert.equal(t.f.calls[1].url, '/api/bookings');
54	  for (const c of t.f.calls) {
55	    assert.equal(c.options, undefined);
56	  }
57	});
58	
59	test('load: only the three expected listeners are registered', () => {
60	  const t = boot();
61	  for (const [id, el] of Object.entries(t.els)) {
62	    const expected = { 'booking-form': ['submit'], 'filter-date': ['change'], 'show-all': ['click'] }[id] || [];
63	    assert.deepEqual(el.listenerTypes(), expected, id);
64	  }
65	  assert.equal(t.els['filter-date'].listeners('input').length, 0);
66	});
67	
68	test('load: no unexpected globals needed and no stray DOM writes', () => {
69	  const t = boot();
70	  assert.deepEqual(t.log.filter((e) => e[0] !== 'fetch'), []);
71	});
72	
73	// ---------- Rooms ----------
74	
75	test('rooms: fills one option per room in order', async () => {
76	  const t = boot();
77	  t.f.respond(t.rooms, 200, { rooms: ['Aurora', 'Borealis', 'Cosmos'] });
78	  await flush();
79	  const opts = t.els.room.children;
80	  assert.equal(opts.length, 3);
81	  assert.deepEqual(opts.map((o) => o.tagName), ['OPTION', 'OPTION', 'OPTION']);
82	  assert.deepEqual(opts.map((o) => o.value), ['Aurora', 'Borealis', 'Cosmos']);
83	  assert.deepEqual(opts.map((o) => o.textContent), ['Aurora', 'Borealis', 'Cosmos']);
84	});
85	
86	test('rooms: error status shows the error string and leaves select empty', async () => {
87	  const t = boot();
88	  t.f.respond(t.rooms, 500, { error: 'boom' });
89	  await flush();
90	  assert.equal(t.els.error.textContent, 'boom');
91	  assert.equal(t.els.room.children.length, 0);
92	});
93	
94	for (const body of [{ error: 5 }, [], 'x', {}, [{ error: 'x' }], null]) {
95	  test(`rooms: error body ${JSON.stringify(body)} gives fallback message`, async () => {
96	    const t = boot();
97	    t.f.respond(t.rooms, 500, body);
98	    await flush();
99	    assert.equal(t.els.error.textContent, 'Request failed.');
100	    assert.equal(t.els.room.children.length, 0);
101	  });
102	}
103	
104	test('rooms: no reply (fetch rejects)', async () => {
105	  const t = boot();
106	  t.f.fail(t.rooms);
107	  await flush();
108	  assert.equal(t.els.error.textContent, NO_REPLY);
109	  assert.equal(t.els.room.children.length, 0);
110	});
111	
112	test('rooms: json() rejecting on non-204 counts as no reply', async () => {
113	  const t = boot();
114	  t.f.respondRaw(t.rooms, 200, () => Promise.reject(new SyntaxError('bad')));
115	  await flush();
116	  assert.equal(t.els.error.textContent, NO_REPLY);
117	  assert.equal(t.els.room.children.length, 0);
118	});
119	
120	test('rooms: reply arriving after the list reply works', async () => {
121	  const t = boot();
122	  t.f.respond(t.list, 200, { bookings: [B1] });
123	  await flush();
124	  t.f.respond(t.rooms, 200, { rooms: ['Aurora', 'Borealis', 'Cosmos'] });
125	  await flush();
126	  assert.equal(t.els.room.children.length, 3);
127	  assert.equal(itemsOf(t).length, 1);
128	});
129	
130	// ---------- List rendering ----------
131	
132	test('list: renders items in reply order with text node and Cancel button', async () => {
133	  const t = await bootWithList([B1, B2]);
134	  const items = itemsOf(t);
