111	export function createFakeDom() {
112	  const log = [];
113	  const elements = {};
114	  for (const id of IDS) elements[id] = guard(new FakeElement('div', id, log));
115	  const document = {
116	    getElementById: (id) => (Object.hasOwn(elements, id) ? elements[id] : null),
117	    createElement: (tag) => guard(new FakeElement(tag, '', log))
118	  };
119	  return { document, elements, log };
120	}
